// The in-Worker type check of extension source against @composable-os/sdk's types. The check
// itself is in @composable-os/extension-check, shared with `cos ext check` (ADR 0405). Here it gets
// the build-time ESM bundle of `typescript` (generated/typescript.js, which works under
// nodejs_compat) and the declarations generated by scripts/bundle.mjs (generated/sdk-types.ts).
// Their parsed SourceFiles are cached in module scope, so after the first call in an isolate only
// the extension's own files are parsed.
import { createTypechecker, MAX_TYPE_ISSUES } from "@composable-os/extension-check/typecheck";
import { SDK_TYPES } from "../generated/sdk-types.ts";
import ts from "../generated/typescript.js";

export { MAX_TYPE_ISSUES };

/**
 * Type-checks an extension's source (paths relative to the extension root, entry `index.ts`)
 * against @composable-os/sdk. Returns at most MAX_TYPE_ISSUES issues, errors only.
 */
export const typecheckExtension = createTypechecker(ts, SDK_TYPES);
